from ute_common_abstract_core.exceptions import AbstractUeLibException


class UltraCallerTestPhaseException(AbstractUeLibException):
    """Ultra Caller Test Phase Exception"""

    def __init__(self, phase):
        """
        Basic initialization.
        :param phase:
        """
        super(UltraCallerTestPhaseException, self).__init__()
        self.msg = phase

    def __str__(self):
        return "UltraCaller test phase: {} not triggered within time limit".format(self.msg)


class UltraCallerTestTypeResultException(AbstractUeLibException):
    """Ultra Caller Test Type Result Exception"""

    def __init__(self, test_type):
        """
        Basic initialization.
        :param test_type:
        """
        super(UltraCallerTestTypeResultException, self).__init__()
        self.msg = test_type

    def __str__(self):
        return "UltraCaller test type {} was not successful".format(self.msg)


class UltraCallerTestReturnsError(AbstractUeLibException):
    """Ultra Caller Test Returns Error"""
    pass


class UltraCallerActionFailed(AbstractUeLibException):
    """Ultra Caller Command Failed Exception"""

    def __init__(self, action):
        """
        Basic initialization.
        :param action:
        """
        super(UltraCallerActionFailed, self).__init__()
        self.msg = action

    def __str__(self):
        return "UltraCaller action {} was not successful".format(self.msg)


class UltraCallerInvalidInputException(AbstractUeLibException):
    """Ultra Caller Command Failed Exception"""

    def __init__(self, method_name, given_input):
        """
        Basic initialization.
        :param method_name:
        :param given_input:
        """
        super(UltraCallerInvalidInputException, self).__init__()
        self.method_name = method_name
        self.given_input = given_input

    def __str__(self):
        return 'Following input for {} is invalid: {}'.format(self.method_name, self.given_input)


class UltraCallerTestNotRunning(AbstractUeLibException):
    """Ultra Caller Command Failed Exception"""

    def __init__(self, test_name):
        """
        Basic initialization.
        :param test_name:
        """
        super(UltraCallerTestNotRunning, self).__init__()
        self.msg = test_name

    def __str__(self):
        return "UltraCaller test {} is not running".format(self.msg)


class UltraCallerTestStartFailed(AbstractUeLibException):
    pass


class UltraCallerNotSupportedProtocol(AbstractUeLibException):
    pass


class UltraCallerNotSupportedTestType(AbstractUeLibException):
    pass
